// archipelago-voronoi.ts
/**
 * Base game map script - Produces a very random map with different numbers of landmasses and distant lands that may or may not be connected.
 * @packageDocumentation
 */
console.log("Generating using script archipelago-voronoi.ts");

import { assignAdvancedStartRegions } from "#base/maps/assign-advanced-start-region.js";
import { assignStartPositionsFromHexMap } from "#base/maps/assign-starting-plots.js";
import { generateDiscoveries } from "#base/maps/discovery-generator.js";
import * as globals from "#base/maps/map-globals.js";
import { generateMapFeatures } from "#base/scripts/common-generation.js";
import { HexTile } from "#base/scripts/hex-map.js";
import { profileScope } from "#base/scripts/profiling.js";
import { VoronoiArchipelago } from "#base/scripts/voronoi_maps/archipelago.js";

function requestMapData(initParams: MapInitializationParams) {
	console.log(initParams.width);
	console.log(initParams.height);
	console.log(initParams.topLatitude);
	console.log(initParams.bottomLatitude);
	console.log(initParams.wrapX);
	console.log(initParams.wrapY);
	console.log(initParams.mapSize);

	engine.call("SetMapInitData", initParams);
}

async function generateMap() {
	console.log("Generating a map!");
	console.log(`Age - ${GameInfo.Ages.lookup(Game.age)!.AgeType}`);
	const voronoiScope: profileScope = new profileScope("Archipelago Voronoi Generation");

	const iWidth = GameplayMap.getGridWidth();
	const iHeight = GameplayMap.getGridHeight();
	const uiMapSize = GameplayMap.getMapSize();

	const mapInfo = GameInfo.Maps.lookup(uiMapSize);
	if (mapInfo == null) return;

	const iTotalPlayers = Players.getAliveMajorIds().length;

	const startTime: number = Date.now();

	const voronoiMap: VoronoiArchipelago = new VoronoiArchipelago();

	const seaLevelType: string = Configuration.getMapValue("SeaLevel");
	console.log(`Sea Level - ${seaLevelType}`);
	switch (seaLevelType) {
		case "SEA_LEVEL_LOW":
			voronoiMap.setSelectedVariantKey("Sea Level", "Low");
			break;
		case "SEA_LEVEL_HIGH":
			voronoiMap.setSelectedVariantKey("Sea Level", "High");
			break;
	}

	voronoiMap.init({ x: iWidth, y: iHeight });
	voronoiMap.setPrimaryMapSetting(["totalPlayers"], iTotalPlayers);
	voronoiMap.simulate();

	const endTime: number = Date.now();
	console.log(`Initial Voronoi map generation took ${endTime - startTime} ms`);

	generateMapFeatures(voronoiMap.getHexTiles());

	const fertilityGetter = (tile: HexTile) => StartPositioner.getPlotFertilityForCoord(tile.coord.x, tile.coord.y);
	voronoiMap.createMajorPlayerAreas(fertilityGetter);
	const startPositions = assignStartPositionsFromHexMap(voronoiMap.getHexTiles());

	generateDiscoveries(iWidth, iHeight, startPositions, globals.g_PolarWaterRows);

	FertilityBuilder.recalculate(); // Must be after features are added.

	assignAdvancedStartRegions();

	//Tweak the AI so that they build a larger navy for this map type
	const PlayerList: PlayerLibrary[] = Players.getAlive();
	for (const player of PlayerList) {
		if (player.isValid && player.isMajor && player.isAI) {
			const playerAI = player.AI;
			playerAI?.scaleAiPreference("PseudoYieldBiases", "PSEUDOYIELD_STANDING_NAVY_UNIT", 200);
		}
	}
	voronoiScope.end();
}

// Register listeners.
engine.on("RequestMapInitData", requestMapData);
engine.on("GenerateMap", generateMap);
